// ===== SETTINGS (sirf yahi badalna hai) =====
const MAX = 1;               // ek run me kitne candidates. PEHLE 1 se test karo. 35 credits = ~3 phone (har mobile ~9 credit)
const WANT_PHONE = true;     // Apollo sirf personal mobile number ke liye (email Treg se aata hai)
const WANT_EMAIL = false;    // true = Apollo se personal email bhi (1 credit extra)
const PHONE_WEBHOOK = '';    // "Apollo phone webhook" workflow ka Production URL yahan paste karo (zaroori)
// ============================================
// Kaun chuna jaata hai: Enriched + Exact title, jinka Apollo abhi tak check nahi hua, aur jinka phone missing hai
// (WANT_EMAIL ho to email missing wale bhi).
const slug = u => (String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i) || [])[1]?.toLowerCase() || '';
const done = new Set($('Read Apollo_results').all().map(i => slug(i.json.linkedin_url)).filter(Boolean));
const goodEmail = r => r.email && /^(valid|verified)/i.test(String(r.email_status || '')) && !/guess|check/i.test(String(r.email_status || ''));
const score = r => (r.open_to_work === 'Yes' ? 5 : 0) + (!r.email ? 3 : goodEmail(r) ? 0 : 2) + (WANT_PHONE && !r.phone ? 2 : 0)
  + (/senior|lead|manager/i.test(r.seniority || '') ? 1 : 0) + Math.min(3, Number(r.servicenow_experience_years || r.ai_ml_experience_years || 0) / 3);
const take = (node, tab) => $(node).all().map(i => i.json)
  .filter(r => r.linkedin_url && slug(r.linkedin_url) && !done.has(slug(r.linkedin_url)))
  .filter(r => ['Enriched', 'Talent-pool ready'].includes(r.readiness) && r.title_match === 'Exact')
  .filter(r => !/apollo/i.test(String(r.contact_source || '')) && !/apollo checked/i.test(String(r.notes || '')))
  .filter(r => (WANT_PHONE && !r.phone) || (WANT_EMAIL && !goodEmail(r)))
  .sort((a, b) => score(b) - score(a))
  .map(r => ({ tab, row: r }));
const sn = take('Read ServiceNow rows', 'ServiceNow'), ai = take('Read AI_ML rows', 'AI_ML');
const picks = [];
while (picks.length < MAX && (sn.length || ai.length)) {
  if (sn.length) picks.push(sn.shift());
  if (picks.length < MAX && ai.length) picks.push(ai.shift());
}
if (WANT_PHONE && !PHONE_WEBHOOK.startsWith('https://')) throw new Error('WANT_PHONE true hai lekin PHONE_WEBHOOK khali hai. Webhook workflow ka Production URL paste karo.');
return picks.map(({ tab, row: r }) => {
  const url = String(r.linkedin_url).replace('://in.linkedin.com', '://www.linkedin.com').replace(/\/+$/, '');
  const parts = String(r.name || '').replace(/\s+[A-Z]\.?$/, '').trim().split(/\s+/);
  const body = { linkedin_url: url, first_name: parts[0] || undefined, last_name: parts.length > 1 ? parts.slice(1).join(' ') : undefined,
    organization_name: r.current_company || undefined, reveal_personal_emails: WANT_EMAIL };
  if (WANT_PHONE && !r.phone) { body.reveal_phone_number = true; body.webhook_url = `${PHONE_WEBHOOK}?li=${encodeURIComponent(r.linkedin_url)}&tab=${tab}`; }
  return { json: { _tab: tab, _row: r, _phone: WANT_PHONE && !r.phone, body } };
});

// Apollo jawab -> (1) sheet tab update  (2) MongoDB apollo_* fields  (3) Apollo_results row  (4) stats
const picks = $('Pick candidates').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const now = new Date(Date.now() + 5.5 * 3600e3);
const today = now.toISOString().slice(0, 10), stamp = now.toISOString().slice(0, 16).replace('T', ' ');
const norm = u => String(u || '').replace('://in.linkedin.com', '://www.linkedin.com').toLowerCase().replace(/\/+$/, '');
const goodEmail = r => r.email && /^(valid|verified)/i.test(String(r.email_status || ''));
const st = { stamp, requested: picks.length, matched: 0, noMatch: 0, errors: 0, verified: 0, otherEmail: 0, personal: 0, emailsAdded: 0, phonesAsked: 0, credits: 0, errorText: '' };
const out = [];
picks.forEach((pk, i) => {
  const r = pk._row, tab = pk._tab, body = res[i] || {};
  const p = body.person || null;
  const err = body.error || body.message || (body.errors && JSON.stringify(body.errors)) || '';
  const sheet = { linkedin_url: r.linkedin_url, last_updated: today };
  const mongo = { linkedin_url: norm(r.linkedin_url), apollo_checked_at: stamp };
  const log = { 'Checked at': stamp, pool: tab === 'AI_ML' ? 'AI/ML' : 'ServiceNow', name: r.name, linkedin_url: r.linkedin_url };
  if (!p) {
    if (err) { st.errors++; st.errorText = String(err).slice(0, 200); }
    else st.noMatch++;
    Object.assign(mongo, { apollo_status: err ? 'Error' : 'No match' });
    Object.assign(log, { matched: err ? 'Error' : 'No', 'what changed in sheet': '-', notes: String(err).slice(0, 200) });
    sheet.notes = `${r.notes || ''}; Apollo checked ${today}: ${err ? 'error' : 'no match'}`.replace(/^; /, '');
    out.push({ json: { _tab: tab, sheet, mongo, log } });
    return;
  }
  st.matched++;
  const email = p.email && !/email_not_unlocked|domain\.com$/i.test(p.email) ? p.email : '';
  const es = String(p.email_status || (email ? 'unknown' : 'unavailable')).toLowerCase();
  const personal = (p.personal_emails || []).find(Boolean) || '';
  const company = p.organization?.name || (p.employment_history || []).find(e => e.current)?.organization_name || '';
  const phones = (p.phone_numbers || []).map(x => x.sanitized_number || x.raw_number).filter(Boolean);
  st.credits += 1;  // Apollo: ~1 credit per matched person (+8 per mobile, counted below)
  if (pk._phone) st.phonesAsked++;
  if (personal) st.personal++;
  const changed = [];
  if (email && es === 'verified') {
    st.verified++;
    if (email.toLowerCase() !== String(r.email || '').toLowerCase() || !goodEmail(r)) {
      Object.assign(sheet, { email, email_status: 'Verified (Apollo)', contact_source: 'Apollo' }); changed.push('email (verified)'); st.emailsAdded++;
    }
  } else if (email) {
    st.otherEmail++;
    if (!r.email) { Object.assign(sheet, { email, email_status: `Apollo ${es} - not verified`, contact_source: 'Apollo' }); changed.push('email (not verified)'); st.emailsAdded++; }
  } else if (personal && !r.email) {
    Object.assign(sheet, { email: personal, email_status: 'Personal email (Apollo)', contact_source: 'Apollo' }); changed.push('personal email'); st.emailsAdded++;
  }
  if (phones[0] && !r.phone) { Object.assign(sheet, { phone: phones[0], phone_status: 'Apollo' }); changed.push('phone'); }
  if (company && !r.current_company) { sheet.current_company = company; changed.push('company'); }
  sheet.notes = `${r.notes || ''}; Apollo checked ${today}: ${changed.length ? changed.join(', ') : 'nothing new'}${personal && sheet.email !== personal ? ' | personal email ' + personal : ''}`.replace(/^; /, '');
  Object.assign(mongo, { apollo_status: 'Matched', apollo_id: p.id || '', apollo_email: email, apollo_email_status: email ? es : 'unavailable',
    apollo_personal_email: personal, apollo_phone: phones[0] || (pk._phone ? 'requested' : ''), apollo_title: p.title || '', apollo_company: company,
    apollo_city: [p.city, p.state].filter(Boolean).join(', ') });
  Object.assign(log, { matched: 'Yes', 'Apollo title / company': [p.title, company].filter(Boolean).join(' / '), 'Apollo email': email, 'email status': email ? es : 'unavailable',
    'personal email': personal, phone: phones[0] || (pk._phone ? 'requested (webhook)' : ''), 'what changed in sheet': changed.join(', ') || 'nothing', notes: '' });
  out.push({ json: { _tab: tab, sheet, mongo, log } });
});
if (!out.length) return [];
out[0].json._stats = st;
return out;

const s = $('Build updates').first().json._stats;
const notes = `Apollo: ${s.matched} matched of ${s.requested}, ${s.noMatch} no match, ${s.errors} errors. Emails: ${s.verified} verified, ${s.otherEmail} unverified, ${s.personal} personal. `
  + `Added to sheet: ${s.emailsAdded} emails. Phones requested: ${s.phonesAsked}. Credits ~${s.credits + s.phonesAsked * 8}${s.errorText ? '. Error: ' + s.errorText : ''}`;
return [{ json: {
  sheet: { 'Run date': s.stamp, 'Flow': 'n8n (apollo)', 'Queries': 0, 'Google results': '', 'LinkedIn profiles found': s.requested,
    'Rejected (not India / wrong title / duplicate)': s.noMatch, 'New rows added': `${s.matched} matched`, 'Apify cost ($)': 0, 'Notes': notes },
  mongo: { run_at: s.stamp, flow: 'n8n (apollo)', found: s.requested, rejected: s.noMatch, added: `${s.matched} matched`, cost: 0,
    matched: s.matched, emails_added: s.emailsAdded, verified: s.verified, credits: s.credits + s.phonesAsked * 8, notes, error: s.errors && !s.matched ? s.errorText : '' },
} }];
